import numpy as np
from scipy.optimize import curve_fit
m=P<0.8
x=t[m]; y=dP_dt[m]; p=P[m]
forms={
'pow':(lambda X,a,b,c,d: -a*X[0]**b - c*X[1] - d*X[1]**2, [2,0.5,0.1,0.01]),
'sqrt_t':(lambda X,a,b,c,d: -a*np.sqrt(X[0])-b*X[0]-c*X[1]-d*X[1]**2,[1,0.5,0.1,0.1]),
'log':(lambda X,a,b,c,d: -a*np.log(1+b*X[0])-c*X[1]-d*X[1]**2,[3,0.5,0.1,0.1]),
'sat':(lambda X,a,b,c,d: -a*X[0]/(1+b*X[0])-c*X[1]-d*X[1]**2,[3,0.1,0.1,0.1]),
}
for k,(f,p0) in forms.items():
    try:
        pr,_=curve_fit(f,(x,p),y,p0=p0,maxfev=20000)
        res=f((x,p),*pr)-y
        print(k,np.round(pr,4),np.max(abs(res)))
    except Exception as e: print(k,e)
